item.content:encoded:
.topbar-marquee{
	overflow: hidden;
	height: 50px;
}
.rs-enable-sticky.rs-header-sticky .header-shape:after {
	background: transparent;
}
.rs-enable-sticky.rs-header-sticky .hfe-site-logo-set {
	position: relative;
	top: -8px;
}
@media only screen and (min-width: 992px){
	.e-con.e-con-boxed > .e-con-inner{
		max-width: 1315px;
	}
}
#pre-load {
  z-index: 999999;
}
body.logged-in header.single-header.rs-enable-sticky header.elementor-element {
    top: 0;
}
